CREATE OR REPLACE VIEW `budjettihaukka-gpt.valtiodata.dim_data_source_v1` AS
SELECT *, '1.0.0' AS contract_version
FROM UNNEST([
  STRUCT('valtiokonttori_monthly_central_government_finance' AS source_id, 'Valtion taloushallinnon kuukausidata' AS title_fi, 'Valtiokonttori' AS organization, 'https://www.tutkihallintoa.fi/valtiontalous/valtion-taloustiedot/' AS source_url, 'valtion kirjanpito ja talousarvio' AS accounting_basis, 'monthly' AS update_frequency, 'Kuukausikertymä ei ole sama asia kuin kansantalouden tilinpidon suoriteperusteinen meno. Keskeneräistä vuotta ei saa verrata täyteen vuoteen ilman näkyvää osavuosimerkintää.' AS caveat_fi),
  STRUCT('statfin_cost_of_living_11xm' AS source_id, 'Elinkustannusindeksi 1951:10=100' AS title_fi, 'Tilastokeskus' AS organization, 'https://pxdata.stat.fi/PxWeb/api/v1/fi/StatFin/khi/11xm.px' AS source_url, 'kuluttajahintojen muutos' AS accounting_basis, 'annual' AS update_frequency, 'CPI-oikaisu kuvaa rahan ostovoimaa. Se ei mittaa julkisten palvelujen tuotantokustannusten tai tuotoksen volyymin muutosta.' AS caveat_fi),
  STRUCT('statfin_population_midyear_11s1' AS source_id, 'Keskiväkiluku' AS title_fi, 'Tilastokeskus' AS organization, 'https://pxdata.stat.fi/PxWeb/api/v1/fi/StatFin/vaerak/11s1.px' AS source_url, 'kalenterivuoden keskiväkiluku' AS accounting_basis, 'annual' AS update_frequency, 'Koko maan keskiväkiluku; ei sovellu aluekohtaisen henkeä kohti -luvun nimittäjäksi.' AS caveat_fi),
  STRUCT('statfin_national_accounts_15a9' AS source_id, 'Bruttokansantuote markkinahintaan, käyvin hinnoin' AS title_fi, 'Tilastokeskus' AS organization, 'https://pxdata.stat.fi/PxWeb/api/v1/fi/StatFin/ntp/15a9.px' AS source_url, 'ESA 2010 kansantalouden tilinpito' AS accounting_basis, 'annual' AS update_frequency, 'BKT ja valtion budjettikirjanpito ovat eri laskentakehikoita. BKT-osuus on vertailusuhde, ei budjetin osuus kansantalouden tilinpidon valtionhallinnon menoista.' AS caveat_fi),
  STRUCT('statfin_central_government_edp_debt_11yv' AS source_id, 'Valtionhallinnon EDP-velka' AS title_fi, 'Tilastokeskus' AS organization, 'https://pxdata.stat.fi/PxWeb/api/v1/fi/StatFin/jyev/11yv.px' AS source_url, 'ESA 2010 / EDP, sulauttamaton valtionhallinnon sektori S1311' AS accounting_basis, 'quarterly' AS update_frequency, 'EDP-velka ei ole sama käsite kuin Valtiokonttorin valtionvelka. Vuosiarvo on neljännen vuosineljänneksen kanta, ei vuoden virta.' AS caveat_fi),
  STRUCT('vm_budget_documents' AS source_id, 'Talousarvioesitykset ja lisätalousarviot' AS title_fi, 'Valtiovarainministeriö' AS organization, 'https://budjetti.vm.fi/' AS source_url, 'talousarvio' AS accounting_basis, 'per budget document' AS update_frequency, 'Budjetoitu määrä ei ole toteuma; lisätalousarviot esitetään erillisenä muutoksena.' AS caveat_fi)
])
